mapper.select:
SELECT
FROM spots s LEFT JOIN place_groups pg ON pg.id = s.legacy_place_group_id LEFT JOIN poi_categories c ON c.id = s.category_id LEFT JOIN pois p ON p.spot_id = s.id AND p.status = 1 AND COALESCE(p.area_code, '') != 'route' AND COALESCE(p.area_code, '') != 'campus_summary' LEFT JOIN spot_tag_relations str ON str.spot_id = s.id
GROUP BY s.id, s.legacy_place_group_id, s.representative_poi_id, s.category_id, c.name, s.name, s.short_name, s.spot_type, s.province, s.city, s.district, s.address, s.description, s.cover_image, s.longitude, s.latitude, s.location_radius_m, s.rating, s.hotness, s.visit_count, s.status, pg.name, pg.route_graph_status ORDER BY CASE WHEN s.legacy_place_group_id = 3 THEN 1 WHEN s.legacy_place_group_id = 4 THEN 2 WHEN s.legacy_place_group_id = 5 THEN 3 WHEN s.legacy_place_group_id = 6 THEN 4 ELSE 20 END, s.hotness DESC, s.id ASC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE spots
SET representative_poi_id = #{representativePoiId}
WHERE id = #{spotId}

UPDATE spots
SET status = #{status}
WHERE id = #{id}

UPDATE pois
SET status = #{status}
WHERE id = #{poiId}
  AND (
    poi_role IN ('spot_summary', 'spot_legacy')
    OR area_code IN ('spot_summary', 'campus_summary')
  )

mapper.sql:
WHERE COALESCE(p.area_code, '') != 'route' AND COALESCE(p.area_code, '') != 'campus_summary' AND COALESCE(p.area_code, '') != 'spot_summary' AND ( p.spot_id = #{spotId}
OR p.place_group_id = #{placeGroupId}
)
AND ( p.name LIKE CONCAT('%', #{keyword}, '%') OR p.area_name LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%') OR p.address LIKE CONCAT('%', #{keyword}, '%') )
AND p.status = #{status}
AND (p.map_x IS NULL OR p.map_y IS NULL)
AND (p.longitude IS NULL OR p.latitude IS NULL)
AND NOT EXISTS ( SELECT 1 FROM route_edges e WHERE e.from_poi_id = p.id OR e.to_poi_id = p.id )
AND (p.image_url IS NULL OR p.image_url = '')

mapper.select:
SELECT
FROM pois p JOIN poi_categories c ON c.id = p.category_id
ORDER BY p.status DESC, p.area_code ASC, p.id ASC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE pois
SET status = #{status}
WHERE id = #{id}
  AND COALESCE(area_code, '') != 'route'
  AND COALESCE(area_code, '') != 'campus_summary'

mapper.select:
SELECT id, name, tag_type AS tagType FROM tags
tag_type = #{tagType}
ORDER BY CASE tag_type WHEN 'poi' THEN 1 WHEN 'interest' THEN 2 ELSE 9 END, id ASC

SELECT id
FROM tags
WHERE name = #{name}
  AND tag_type = #{tagType}
LIMIT 1
